                while i < n and s[i] == '0':
                    i += 1
                length = i - start
                group_id = len(zero_groups)
                zero_groups.append((start, length))
                for idx in range(start, i):
                    zero_group_index[idx] = group_id
            else:
                i += 1

        m = len(zero_groups)
        if m == 0:
            return [total_ones] * len(queries)

