        # Sparse table for RMQ over adj_sums
        st = []
        if adj_sums:
            k = len(adj_sums).bit_length() - 1
            st = [[0] * len(adj_sums) for _ in range(k + 1)]
            st[0] = adj_sums[:]
            for p in range(1, k + 1):
                length = 1 << (p - 1)
                for j in range(len(adj_sums) - (1 << p) + 1):
