    vector<int> maxActiveSectionsAfterTrade(string s, vector<vector<int>>& queries) {
        int n = s.length();
        int totalOnes = 0;
        for (char c : s) if (c == '1') totalOnes++;

        vector<pair<int, int>> zeroGroups;
        vector<int> zeroGroupIndex(n, -1);
        int i = 0;
        while (i < n) {
            if (s[i] == '0') {
                int start = i;
                while (i < n && s[i] == '0') i++;
                int len = i - start;
                int gid = zeroGroups.size();
                zeroGroups.emplace_back(start, len);
                for (int idx = start; idx < i; ++idx) zeroGroupIndex[idx] = gid;
            } else {
                i++;
            }
        }

        int m = zeroGroups.size();
        if (m == 0) return vector<int>(queries.size(), totalOnes);

        vector<int> adjSums;
        for (int idx = 0; idx < m - 1; ++idx) {
            adjSums.push_back(zeroGroups[idx].second + zeroGroups[idx + 1].second);
        }

        st.clear();
        if (!adjSums.empty()) {
            int k = 31 - __builtin_clz(adjSums.size());
            st.assign(k + 1, vector<int>(adjSums.size()));
            st[0] = adjSums;
            for (int p = 1; p <= k; ++p) {
                int len = 1 << (p - 1);
                for (size_t j = 0; j + (1 << p) <= adjSums.size(); ++j) {
                    st[p][j] = max(st[p - 1][j], st[p - 1][j + len]);
                }
            }
        }

        vector<int> ans;
        ans.reserve(queries.size());

        for (const auto& q : queries) {
            int l = q[0], r = q[1];
            int g_l = zeroGroupIndex[l];
            int g_r = zeroGroupIndex[r];
            int bestGain = 0;

            if (g_l == -1 && g_r == -1) {
                int left_idx = 0;
                while (left_idx < m && zeroGroups[left_idx].first < l) left_idx++;
                int right_idx = m - 1;
                while (right_idx >= 0 && zeroGroups[right_idx].first + zeroGroups[right_idx].second - 1 > r) right_idx--;
                if (left_idx <= right_idx - 1) {
                    bestGain = max(bestGain, querySt(left_idx, right_idx - 1));
                }
            } else if (g_l != -1 && g_r == -1) {
                int remLen = zeroGroups[g_l].second - (l - zeroGroups[g_l].first);
                if (g_l + 1 < m && zeroGroups[g_l + 1].first + zeroGroups[g_l + 1].second - 1 <= r) {
                    bestGain = max(bestGain, remLen + zeroGroups[g_l + 1].second);
                }
                int left_idx = g_l + 1;
                int right_idx = m - 1;
                while (right_idx >= 0 && zeroGroups[right_idx].first + zeroGroups[right_idx].second - 1 > r) right_idx--;
                if (left_idx <= right_idx - 1) {
                    bestGain = max(bestGain, querySt(left_idx, right_idx - 1));
                }
            } else if (g_l == -1 && g_r != -1) {
                int remLen = r - zeroGroups[g_r].first + 1;
                if (g_r - 1 >= 0 && zeroGroups[g_r - 1].first >= l) {
                    bestGain = max(bestGain, zeroGroups[g_r - 1].second + remLen);
                }
                int left_idx = 0;
                while (left_idx < m && zeroGroups[left_idx].first < l) left_idx++;
                int right_idx = g_r - 1;
                if (left_idx <= right_idx - 1) {
                    bestGain = max(bestGain, querySt(left_idx, right_idx - 1));
